SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state", "n_short", "n_price", "n_due", 'hold_ar' AS "route", 'overdue invoices' AS "verdict_reason"
FROM (SELECT "t27"."order_number", "t27"."customer", "t27"."channel", "t27"."fulfilling_warehouse", "t27"."value", "t27"."placed_date", "t27"."state", COALESCE("t27"."n_short", 0) AS "n_short", COALESCE("t27"."n_price", 0) AS "n_price", COALESCE("t33"."n_due", 0) AS "n_due"
        FROM (SELECT "t15"."order_number", "t15"."customer", "t15"."channel", "t15"."fulfilling_warehouse", "t15"."value", "t15"."placed_date", "t15"."state", "t15"."n_short", "t26"."n_price"
                FROM (SELECT "t0"."order_number", "t0"."customer", "t0"."channel", "t0"."fulfilling_warehouse", "t0"."value", "t0"."placed_date", "t0"."state", "t14"."n_short"
                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                FROM "order"
                                WHERE "state" IN ('held', 'placed')) AS "t0"
                            LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_short"
                                FROM (SELECT "t9"."order_number", "t9"."customer", "t9"."channel", "t9"."fulfilling_warehouse", "t9"."value", "t9"."placed_date", "t9"."state", "t9"."line_no", "t9"."item", "t9"."quantity", "t9"."unit_price", "t9"."ext_sales_price", "t9"."warehouse", "t9"."sold_date", "t9"."customer0", "t9"."channel0", "t9"."as_of_date", "t9"."quantity_on_hand", "t9"."_ttrp_g_n8_0", "t9"."_ttrp_g_n8_1", "t9"."_ttrp_d_n8", "t10"."warehouse" AS "warehouse0", "t10"."from_date", "t10"."to_date", "t10"."reason", COALESCE("t9"."quantity_on_hand", 0) AS "on_hand", "t10"."warehouse" IS NOT NULL AS "outage"
                                        FROM (SELECT "t3"."order_number", "t3"."customer", "t3"."channel", "t3"."fulfilling_warehouse", "t3"."value", "t3"."placed_date", "t3"."state", "t3"."line_no", "t3"."item", "t3"."quantity", "t3"."unit_price", "t3"."ext_sales_price", "t3"."warehouse", "t3"."sold_date", "t3"."customer0", "t3"."channel0", "t8"."as_of_date", "t8"."quantity_on_hand", "t8"."_ttrp_g_n8_0", "t8"."_ttrp_g_n8_1", "t8"."_ttrp_d_n8"
                                                FROM (SELECT "t2"."order_number", "t2"."customer", "t2"."channel", "t2"."fulfilling_warehouse", "t2"."value", "t2"."placed_date", "t2"."state", "sales_line"."line_no", "sales_line"."item", "sales_line"."quantity", "sales_line"."unit_price", "sales_line"."ext_sales_price", "sales_line"."warehouse", "sales_line"."sold_date", "sales_line"."customer" AS "customer0", "sales_line"."channel" AS "channel0"
                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                FROM "order"
                                                                WHERE "state" IN ('held', 'placed')) AS "t2"
                                                            INNER JOIN "sales_line" ON "t2"."order_number" = "sales_line"."order_number") AS "t3"
                                                    LEFT JOIN (SELECT "t4"."as_of_date", "t4"."item", "t4"."warehouse", "t4"."quantity_on_hand", "t4"."_ttrp_g_n8_0", "t4"."_ttrp_g_n8_1", "t4"."_ttrp_d_n8"
                                                        FROM (SELECT "as_of_date", "item", "warehouse", "quantity_on_hand", CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1", CASE WHEN "as_of_date" IS NULL THEN 'n' ELSE 'v' || CAST("as_of_date" AS VARCHAR) END AS "_ttrp_d_n8"
                                                                FROM "inventory") AS "t4"
                                                            INNER JOIN (SELECT CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1", CASE WHEN MAX("as_of_date") IS NULL THEN 'n' ELSE 'v' || CAST(MAX("as_of_date") AS VARCHAR) END AS "_ttrp_dm_n8"
                                                                FROM "inventory"
                                                                GROUP BY CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END, CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END) AS "t7" ON "t4"."_ttrp_g_n8_0" = "t7"."_ttrp_g_n8_0" AND "t4"."_ttrp_g_n8_1" = "t7"."_ttrp_g_n8_1" AND "t4"."_ttrp_d_n8" = "t7"."_ttrp_dm_n8") AS "t8" ON "t3"."item" = "t8"."item" AND "t3"."warehouse" = "t8"."warehouse") AS "t9"
                                            LEFT JOIN (SELECT *
                                                FROM "warehouse_outage"
                                                WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t10" ON "t9"."warehouse" = "t10"."warehouse") AS "t11"
                                WHERE "t11"."outage" OR "t11"."on_hand" < "t11"."quantity"
                                GROUP BY "order_number") AS "t14" ON "t0"."order_number" = "t14"."order_number") AS "t15"
                    LEFT JOIN (SELECT "order_number0" AS "order_number", COUNT("line_no0") AS "n_price"
                        FROM (SELECT "t18"."order_number", "t18"."line_no", "t18"."item", "t18"."unit_price", "t18"."customer", "t18"."channel", "t18"."placed_date", "t22"."order_number" AS "order_number0", "t22"."line_no" AS "line_no0", "t22"."price"
                                FROM (SELECT "sales_line0"."order_number", "sales_line0"."line_no", "sales_line0"."item", "sales_line0"."unit_price", "t17"."customer", "t17"."channel", "t17"."placed_date"
                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                FROM "order"
                                                WHERE "state" IN ('held', 'placed')) AS "t17"
                                            INNER JOIN "sales_line" AS "sales_line0" ON "t17"."order_number" = "sales_line0"."order_number") AS "t18"
                                    INNER JOIN (SELECT "t21"."order_number", "t21"."line_no", COALESCE("customer_price"."price", "price_list"."price") AS "price"
                                        FROM (SELECT "sales_line1"."order_number", "sales_line1"."line_no", "sales_line1"."item", "sales_line1"."unit_price", "t20"."customer", "t20"."channel", "t20"."placed_date"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t20"
                                                    INNER JOIN "sales_line" AS "sales_line1" ON "t20"."order_number" = "sales_line1"."order_number") AS "t21"
                                            LEFT JOIN "customer_price" ON "t21"."item" = "customer_price"."item" AND "t21"."customer" = "customer_price"."customer" AND "t21"."placed_date" >= "customer_price"."valid_from" AND ("customer_price"."valid_to" IS NULL OR "t21"."placed_date" <= "customer_price"."valid_to")
                                            LEFT JOIN "price_list" ON "t21"."item" = "price_list"."item" AND "t21"."channel" = "price_list"."channel" AND "t21"."placed_date" >= "price_list"."valid_from" AND ("price_list"."valid_to" IS NULL OR "t21"."placed_date" <= "price_list"."valid_to")) AS "t22" ON "t18"."order_number" = "t22"."order_number" AND "t18"."line_no" = "t22"."line_no") AS "t23"
                        WHERE "t23"."price" IS NULL OR ABS("t23"."unit_price" - "t23"."price") > :tolerance
                        GROUP BY "order_number0") AS "t26" ON "t15"."order_number" = "t26"."order_number") AS "t27"
            LEFT JOIN (SELECT "order_number", COUNT("invoice_id") AS "n_due"
                FROM (SELECT "t29"."order_number", "t29"."customer", "t29"."channel", "t29"."fulfilling_warehouse", "t29"."value", "t29"."placed_date", "t29"."state", "invoice"."invoice_id", "invoice"."order_number" AS "order_number0", "invoice"."issued", "invoice"."due", "invoice"."amount", "invoice"."paid", "invoice"."status"
                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                FROM "order"
                                WHERE "state" IN ('held', 'placed')) AS "t29"
                            INNER JOIN "invoice" ON "t29"."customer" = "invoice"."customer") AS "t30"
                WHERE "t30"."status" = 'open' AND "t30"."due" < :as_of
                GROUP BY "order_number") AS "t33" ON "t27"."order_number" = "t33"."order_number") AS "t34"
WHERE "t34"."n_due" > 0
